#include <iostream>
using namespace std;
int main() {
    /* pokupka - стоимость покупки без скидки,
       itog - окончательная стоимость,
       skidka - скидка при покупке */
    int pokupka, itog, skidka;
    string friday;
    cout << "Введи стоимость покупки" << endl;
    cin >> pokupka;
    cout << "Сегодня пятница? (да/нет)" << endl;
    cin >> friday;
    if (friday == "да")
    {
        skidka = pokupka * 20 / 100;
        itog = pokupka - skidka;
    }
    else
    {
        skidka = pokupka * 3 / 100;
        itog = pokupka - skidka;
    }
    cout << itog << endl;
}

